/**
 * overlay_loader — single bundle anchor that loads a sibling overlay file.
 *
 * Magisk-style "overlay, don't mutate": instead of every patch carving its own
 * anchor into the bundle, this patch injects exactly ONE require near the top
 * of the IIFE that pulls in `ccpatch-overlay.mjs` (generated by the runner
 * alongside the patched bundle). Per-extension shim code lives in that file
 * and registers via __ccpProvide / __ccpRequire instead of bundle anchors.
 *
 * Trade-off: one extra file ships next to the bundle, in exchange for fewer
 * bundle anchors that can drift across upstream versions.
 *
 * Ordering:
 *   phase: 'pre' — runs before esm_compat (post) rewrites the IIFE tail.
 *   We anchor on the CJS-IIFE opening so `require` is the IIFE's local
 *   parameter and is available even after esm_compat rewrites the call to
 *   pass `__hm_require`.
 */

const SENTINEL = '/* [ccpatch overlay-loader] */';

const hook =
  `${SENTINEL} try { require('./ccpatch-overlay.mjs'); } ` +
  `catch (e) { if (e && e.code !== 'MODULE_NOT_FOUND') console.error('[ccpatch] overlay load failed:', e && e.message); }\n`;

const __cjsIife__ = '(function(exports, require, module, __filename, __dirname) {';

export default {
  name: 'overlay_loader',
  version: '1.0.0',
  category: 'infrastructure',
  description: 'Overlay loader — single anchor that loads ./ccpatch-overlay.mjs (Magisk-style overlay)',
  capabilities: ['fs'],
  phase: 'pre',
  required: true,
  verify: {
    present: ["require('./ccpatch-overlay.mjs')", SENTINEL],
    count: { present: 2 },
  },
  apply: (code) => {
    if (code.includes(SENTINEL)) return code; // idempotent
    if (code.includes(__cjsIife__)) {
      return code.replace(__cjsIife__, () => __cjsIife__ + ' ' + hook);
    }
    // Native-ESM fallback: inject after shebang using createRequire.
    const shebang = '#!/usr/bin/env node';
    if (code.startsWith(shebang)) {
      const esmHook =
        `${SENTINEL} try { ` +
        `const { createRequire: __ccpCR } = await import('node:module'); ` +
        `__ccpCR(import.meta.url)('./ccpatch-overlay.mjs'); ` +
        `} catch (e) { if (e && e.code !== 'MODULE_NOT_FOUND') console.error('[ccpatch] overlay load failed:', e && e.message); }\n`;
      const nl = code.indexOf('\n') + 1;
      return code.slice(0, nl) + esmHook + code.slice(nl);
    }
    console.warn('  [!] overlay_loader: no anchor found — skipping');
    return code;
  },
};
